-- Table to store the optimized portfolios generated by Markowitz
CREATE TABLE IF NOT EXISTS optimized_portfolios (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    portfolio_type TEXT NOT NULL, -- 'Max Sharpe' or 'Min Volatility'
    weights_json TEXT NOT NULL,   -- JSON string with the weights
    expected_return REAL,
    expected_volatility REAL,
    sharpe_ratio REAL
);

-- Table to store the AI reports generated by Gemini
CREATE TABLE IF NOT EXISTS ai_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ticker TEXT NOT NULL,
    recommendation TEXT NOT NULL,
    macro_context TEXT NOT NULL,
    risk_assessment TEXT NOT NULL
);